{"command":"cat << 'EOF' > src/editor.rs
use crate::cli::Editor;
use shlex;

pub fn get_editor_command(
    editor_flag: Option<Editor>,
    custom_cmd_flag: Option<&str>,
) -> Result<String, String> {
    if let Some(cmd) = custom_cmd_flag {
        validate_custom_command(cmd)?;
        return Ok(cmd.to_string());
    }

    if let Some(editor) = editor_flag {
        return Ok(editor_to_template(editor));
    }

    if let Ok(val) = std::env::var("IGREP_EDITOR") {
        if !val.trim().is_empty() {
            return parse_editor_env("IGREP_EDITOR", &val);
        }
    }

    if let Ok(val) = std::env::var("IGREP_CUSTOM_EDITOR") {
        if !val.trim().is_empty() {
            validate_custom_command(&val)?;
            return Ok(val);
        }
    }

    if let Ok(val) = std::env::var("VISUAL") {
        if !val.trim().is_empty() {
            return parse_editor_env("VISUAL", &val);
        }
    }

    if let Ok(val) = std::env::var("EDITOR") {
        if !val.trim().is_empty() {
            return parse_editor_env("EDITOR", &val);
        }
    }

    Ok("vim +{line_number} {file_name}".to_string())
}

pub fn validate_custom_command(cmd: &str) -> Result<(), String> {
    let tokens = shlex::split(cmd).unwrap_or_default();
    if tokens.len() < 2 {
        return Err(format!(
            "Incorrect editor command: '{}'\n\nCaused by:\n    Expected program and its arguments",
            cmd
        ));
    }

    let file_name_count = tokens.iter().filter(|t| t.contains("{file_name}")).count();
    if file_name_count != 1 {
        return Err(format!(
            "Incorrect editor command: '{}'\n\nCaused by:\n    Expected one occurrence of '{{file_name}}'.",
            cmd
        ));
    }

    let line_num_count = tokens.iter().filter(|t| t.contains("{line_number}")).count();
    if line_num_count != 1 {
        return Err(format!(
            "Incorrect editor command: '{}'\n\nCaused by:\n    Expected one occurrence of '{{line_number}}'.",
            cmd
        ));
    }

    Ok(())
}

fn parse_editor_env(env_var: &str, val: &str) -> Result<String, String> {
    if val.contains("{file_name}") || val.contains("{line_number}") {
        validate_custom_command(val)?;
        return Ok(val.to_string());
    }

    match val.trim().to_lowercase().as_str() {
        "vim" => Ok(editor_to_template(Editor::Vim)),
        "neovim" => Ok(editor_to_template(Editor::Neovim)),
        "nvim" => Ok(editor_to_template(Editor::Nvim)),
        "nano" => Ok(editor_to_template(Editor::Nano)),
        "code" => Ok(editor_to_template(Editor::Code)),
        "vscode" => Ok(editor_to_template(Editor::Vscode)),
        "code-insiders" => Ok(editor_to_template(Editor::CodeInsiders)),
        "emacs" => Ok(editor_to_template(Editor::Emacs)),
        "emacsclient" => Ok(editor_to_template(Editor::Emacsclient)),
        "hx" => Ok(editor_to_template(Editor::Hx)),
        "helix" => Ok(editor_to_template(Editor::Helix)),
        "subl" => Ok(editor_to_template(Editor::Subl)),
        "sublime-text" => Ok(editor_to_template(Editor::SublimeText)),
        "micro" => Ok(editor_to_template(Editor::Micro)),
        "intellij" => Ok(editor_to_template(Editor::Intellij)),
        "goland" => Ok(editor_to_template(Editor::Goland)),
        "pycharm" => Ok(editor_to_template(Editor::Pycharm)),
        "less" => Ok(editor_to_template(Editor::Less)),
        "fresh" => Ok(editor_to_template(Editor::Fresh)),
        _ => Err(format!(
            "\"{}\" read from ${}, possible variants: [vim, neovim, nvim, nano, code, vscode, code-insiders, emacs, emacsclient, hx, helix, subl, sublime-text, micro, intellij, goland, pycharm, less, fresh]\n\nCaused by:\n    invalid variant: {}",
            val, env_var, val
        )),
    }
}

pub fn editor_to_template(editor: Editor) -> String {
    match editor {
        Editor::Vim => "vim +{line_number} {file_name}".to_string(),
        Editor::Neovim | Editor::Nvim => "nvim +{line_number} {file_name}".to_string(),
        Editor::Nano => "nano +{line_number} {file_name}".to_string(),
        Editor::Code | Editor::Vscode => "code -g {file_name}:{line_number}".to_string(),
        Editor::CodeInsiders => "code-insiders -g {file_name}:{line_number}".to_string(),
        Editor::Emacs => "emacs -nw +{line_number} {file_name}".to_string(),
        Editor::Emacsclient => "emacsclient -nw +{line_number} {file_name}".to_string(),
        Editor::Hx => "hx {file_name}:{line_number}".to_string(),
        Editor::Helix => "helix {file_name}:{line_number}".to_string(),
        Editor::Subl | Editor::SublimeText => "subl {file_name}:{line_number}".to_string(),
        Editor::Micro => "micro +{line_number} {file_name}".to_string(),
        Editor::Intellij => "idea --line {line_number} {file_name}".to_string(),
        Editor::Goland => "goland --line {line_number} {file_name}".to_string(),
        Editor::Pycharm => "pycharm --line {line_number} {file_name}".to_string(),
        Editor::Less => "less +{line_number} {file_name}".to_string(),
        Editor::Fresh => "fresh {file_name}:{line_number}".to_string(),
    }
}
EOF
"}

