use ignore::types::TypesBuilder;
use ignore::WalkBuilder;
use regex::RegexBuilder;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::SystemTime;

#[derive(Debug, Clone)]
pub struct MatchItem {
    pub file_path: PathBuf,
    pub line_number: usize,
    pub line_text: String,
    pub spans: Vec<(usize, usize)>,
}

#[derive(Debug, Clone)]
pub struct SearchOptions {
    pub pattern: String,
    pub paths: Vec<PathBuf>,
    pub ignore_case: bool,
    pub smart_case: bool,
    pub hidden: bool,
    pub follow: bool,
    pub word_regexp: bool,
    pub fixed_strings: bool,
    pub multiline: bool,
    pub globs: Vec<String>,
    pub type_matching: Vec<String>,
    pub type_not: Vec<String>,
    pub sort: Option<SortBy>,
    pub sortr: Option<SortBy>,
}

pub fn validate_file_types(types: &[String]) -> Result<(), String> {
    let mut tb = TypesBuilder::new();
    tb.add_defaults();
    let built_types = tb.build().map_err(|e| e.to_string())?;

    for t in types {
        if built_types.matched(t, false).is_none() {
            // Check if t is known in definitions
            let known = built_types.definitions().iter().any(|d| d.name() == t);
            if !known {
                return Err(format!("unrecognized file type: {}", t));
            }
        }
    }
    Ok(())
}

pub fn run_search(opts: &SearchOptions) -> Result<Vec<MatchItem>, String> {
    // Validate file types
    validate_file_types(&opts.type_matching)?;
    validate_file_types(&opts.type_not)?;

    // Build regex pattern
    let mut raw_pat = opts.pattern.clone();
    if opts.fixed_strings {
        raw_pat = regex::escape(&raw_pat);
    }
    if opts.word_regexp {
        raw_pat = format!(r"\b(?:{})\b", raw_pat);
    }

    let mut builder = RegexBuilder::new(&raw_pat);

    if opts.ignore_case {
        builder.case_insensitive(true);
    } else if opts.smart_case {
        let has_uppercase = raw_pat.chars().any(|c| c.is_uppercase());
        builder.case_insensitive(!has_uppercase);
    } else {
        builder.case_insensitive(false);
    }

    if opts.multiline {
        builder.multi_line(true);
    }

    let re = builder.build().map_err(|e| e.to_string())?;

    // Build WalkBuilder
    let root_paths = if opts.paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        opts.paths.clone()
    };

    let mut walker_builder = WalkBuilder::new(&root_paths[0]);
    for p in &root_paths[1..] {
        walker_builder.add(p);
    }

    walker_builder.hidden(!opts.hidden);
    walker_builder.follow_links(opts.follow);

    if !opts.globs.is_empty() {
        let mut ob = OverrideBuilder::new(&root_paths[0]);
        for g in &opts.globs {
            ob.add(g).map_err(|e| e.to_string())?;
        }
        walker_builder.override(ob.build().map_err(|e| e.to_string())?);
    }

    if !opts.type_matching.is_empty() || !opts.type_not.is_empty() {
        let mut tb = TypesBuilder::new();
        tb.add_defaults();
        for t in &opts.type_matching {
            tb.select(t);
        }
        for t in &opts.type_not {
            tb.negate(t);
        }
        walker_builder.types(tb.build().map_err(|e| e.to_string())?);
    }

    let mut matches = Vec::new();

    for result in walker_builder.build() {
        let entry = match result {
            Ok(e) => e,
            Err(_) => continue,
        };

        if !entry.file_type().map_or(false, |ft| ft.is_file()) {
            continue;
