            let mut spans = Vec::new();
            for m in re.find_iter(line) {
                spans.push((m.start(), m.end()));
            }

            if !spans.is_empty() {
                matches.push(MatchItem {
                    file_path: path.to_path_buf(),
                    line_number: line_idx + 1,
                    line_text: line.to_string(),
                    spans,
                });
            }
        }
    }

