    let sort_by = opts.sort.or(opts.sortr);
    let is_reverse = opts.sortr.is_some();

    if let Some(sort_kind) = sort_by {
        sort_matches(&mut matches, sort_kind, is_reverse);
    }

    Ok(matches)
