    match sort_by {
        SortBy::Path => {
            matches.sort_by(|a, b| {
                let cmp = a.file_path.cmp(&b.file_path);
                if cmp == std::cmp::Ordering::Equal {
                    a.line_number.cmp(&b.line_number)
                } else {
                    cmp
                }
            });
        }
        SortBy::Modified => {
            matches.sort_by(|a, b| {
                let time_a = get_mtime(&a.file_path);
                let time_b = get_mtime(&b.file_path);
                let cmp = time_a.cmp(&time_b);
                if cmp == std::cmp::Ordering::Equal {
                    a.file_path.cmp(&b.file_path)
                } else {
                    cmp
                }
            });
        }
        SortBy::Created => {
            matches.sort_by(|a, b| {
                let time_a = get_ctime(&a.file_path);
                let time_b = get_ctime(&b.file_path);
                let cmp = time_a.cmp(&time_b);
                if cmp == std::cmp::Ordering::Equal {
                    a.file_path.cmp(&b.file_path)
                } else {
                    cmp
                }
            });
        }
        SortBy::Accessed => {
            matches.sort_by(|a, b| {
                let time_a = get_atime(&a.file_path);
                let time_b = get_atime(&b.file_path);
                let cmp = time_a.cmp(&time_b);
                if cmp == std::cmp::Ordering::Equal {
                    a.file_path.cmp(&b.file_path)
                } else {
                    cmp
                }
            });
        }
    }

    if reverse {
        matches.reverse();
    }
}

fn get_mtime(path: &Path) -> SystemTime {
    fs::metadata(path)
        .and_then(|m| m.modified())
        .unwrap_or(SystemTime::UNIX_EPOCH)
}

fn get_ctime(path: &Path) -> SystemTime {
    fs::metadata(path)
        .and_then(|m| m.created())
        .unwrap_or(SystemTime::UNIX_EPOCH)
}

fn get_atime(path: &Path) -> SystemTime {
    fs::metadata(path)
        .and_then(|m| m.accessed())
        .unwrap_or(SystemTime::UNIX_EPOCH)
}
