{"command":"cat << 'EOF' > src/app.rs
use crate::cli::{ContextViewer, SortBy};
use crate::editor;
use crate::searcher::{run_search, sort_matches, MatchItem, SearchOptions};
use crate::theme::ThemeColors;
use std::collections::HashSet;
use std::path::PathBuf;

#[derive(Debug, PartialEq, Eq)]
pub enum SearchStatus {
    Searching,
    Finished,
    Error(String),
}

pub struct App {
    pub search_opts: SearchOptions,
    pub matches: Vec<MatchItem>,
    pub filtered_match_indices: HashSet<usize>,
    pub filtered_file_paths: HashSet<PathBuf>,
    pub selected_idx: usize,
    pub search_status: SearchStatus,
    pub editor_cmd_template: String,
    pub theme: ThemeColors,
    pub context_viewer: ContextViewer,
    pub context_viewer_pct: u16,
    pub show_keymap_popup: bool,
    pub keymap_scroll: usize,
    pub show_search_popup: bool,
    pub search_popup_input: String,
    pub status_error_message: Option<String>,
}

impl App {
    pub fn new(
        search_opts: SearchOptions,
        editor_cmd_template: String,
        theme: ThemeColors,
        context_viewer: ContextViewer,
    ) -> Self {
        Self {
            search_opts,
            matches: Vec::new(),
            filtered_match_indices: HashSet::new(),
            filtered_file_paths: HashSet::new(),
            selected_idx: 0,
            search_status: SearchStatus::Searching,
            editor_cmd_template,
            theme,
            context_viewer,
            context_viewer_pct: 50,
            show_keymap_popup: false,
            keymap_scroll: 0,
            show_search_popup: false,
            search_popup_input: String::new(),
            status_error_message: None,
        }
    }

    pub fn execute_search(&mut self) {
        self.search_status = SearchStatus::Searching;
        match run_search(&self.search_opts) {
            Ok(matches) => {
                self.matches = matches;
                self.search_status = SearchStatus::Finished;
                self.selected_idx = 0;
            }
            Err(e) => {
                self.search_status = SearchStatus::Error(e);
            }
        }
    }

    pub fn visible_matches(&self) -> Vec<(usize, &MatchItem)> {
        self.matches
            .iter()
            .enumerate()
            .filter(|(i, m)| {
                !self.filtered_match_indices.contains(i)
                    && !self.filtered_file_paths.contains(&m.file_path)
            })
            .collect()
    }

    pub fn visible_files_count(&self) -> usize {
        let mut paths = HashSet::new();
        for (_, m) in self.visible_matches() {
            paths.insert(&m.file_path);
        }
        paths.len()
    }

    pub fn total_files_count(&self) -> usize {
        let mut paths = HashSet::new();
        for m in &self.matches {
            paths.insert(&m.file_path);
        }
        paths.len()
    }

    pub fn filtered_matches_count(&self) -> usize {
        self.matches.len() - self.visible_matches().len()
    }

    pub fn move_down(&mut self) {
        let visible = self.visible_matches();
        if !visible.is_empty() {
            if self.selected_idx + 1 < visible.len() {
                self.selected_idx += 1;
            }
        }
    }

