cat << 'EOF' > src/ui.rs
use crate::app::{App, SearchStatus};
use crate::cli::ContextViewer;
use ratatui::{
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, BorderType, Borders, Clear, Paragraph},
    Frame,
};
use std::fs;

pub fn draw(f: &mut Frame, app: &App) {
    let size = f.area();

    // Main layout: Vertical split for content and bottom status bar
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(1), Constraint::Length(1)])
        .split(size);

    let content_area = chunks[0];
    let status_area = chunks[1];

    // Render content area based on ContextViewer
    match app.context_viewer {
        ContextViewer::None => {
            let block = Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded);
            let inner = block.inner(content_area);
            f.render_widget(block, content_area);
            render_results_list(f, app, inner);
        }
        ContextViewer::Vertical => {
            let horiz_chunks = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([
                    Constraint::Percentage(100 - app.context_viewer_pct),
                    Constraint::Percentage(app.context_viewer_pct),
                ])
                .split(content_area);

            let left_block = Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded);
            let left_inner = left_block.inner(horiz_chunks[0]);
            f.render_widget(left_block, horiz_chunks[0]);
            render_results_list(f, app, left_inner);

            let right_block = Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded);
            let right_inner = right_block.inner(horiz_chunks[1]);
            f.render_widget(right_block, horiz_chunks[1]);
            render_context_viewer(f, app, right_inner);
        }
        ContextViewer::Horizontal => {
            let vert_chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Percentage(100 - app.context_viewer_pct),
                    Constraint::Percentage(app.context_viewer_pct),
                ])
                .split(content_area);

            let top_block = Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded);
            let top_inner = top_block.inner(vert_chunks[0]);
            f.render_widget(top_block, vert_chunks[0]);
            render_results_list(f, app, top_inner);

            let bottom_block = Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded);
            let bottom_inner = bottom_block.inner(vert_chunks[1]);
            f.render_widget(bottom_block, vert_chunks[1]);
            render_context_viewer(f, app, bottom_inner);
        }
    }

    // Render Status Bar
    render_status_bar(f, app, status_area);

    // Render Popups if active
    if app.show_keymap_popup {
        render_keymap_popup(f, app, size);
    } else if app.show_search_popup {
        render_search_popup(f, app, size);
    }
}

fn render_results_list(f: &mut Frame, app: &App, area: Rect) {
    let visible = app.visible_matches();
    if visible.is_empty() {
        return;
    }

    // Prepare list lines
    let mut lines: Vec<(Option<usize>, Line)> = Vec::new();
    let mut current_path = None;

    for (vis_idx, (_, match_item)) in visible.iter().enumerate() {
        if current_path != Some(&match_item.file_path) {
            current_path = Some(&match_item.file_path);
            let path_str = match_item.file_path.to_string_lossy().to_string();
            let header_line = Line::from(Span::styled(
                path_str,
                Style::default().fg(app.theme.file_header_fg),
            ));
            lines.push((None, header_line));
        }

        // Format line item
        let line_num_str = format!(" {:>1}: ", match_item.line_number);
        let mut spans = vec![Span::styled(
            line_num_str,
            Style::default().fg(app.theme.line_num_fg),
        )];

        // Highlight matched spans in line_text
        let text = &match_item.line_text;
        let mut last_end = 0;
        for &(s, e) in &match_item.spans {
            if s > last_end {
                spans.push(Span::raw(&text[last_end..s]));
            }
            if e <= text.len() && s < e {
                spans.push(Span::styled(
                    &text[s..e],
                    Style::default().fg(app.theme.match_fg),
                ));
            }
            last_end = e;
        }
        if last_end < text.len() {
            spans.push(Span::raw(&text[last_end..]));
        }

        let item_line = Line::from(spans);
        lines.push((Some(vis_idx), item_line));
    }

    // Find row index of currently selected_idx
    let selected_row_idx = lines
        .iter()
        .position(|(v_idx, _)| *v_idx == Some(app.selected_idx))
        .unwrap_or(0);

    // Scrolling logic
    let height = area.height as usize;
    let mut scroll = 0;
    if selected_row_idx >= height {
        scroll = selected_row_idx - height + 1;
    }

    let mut rendered_lines = Vec::new();
    for (row_idx, (vis_idx, mut line)) in lines.into_iter().skip(scroll).take(height).enumerate() {
        let abs_row_idx = scroll + row_idx;
        if abs_row_idx == selected_row_idx {
            // Apply selection style to background
            line.style = line.style.bg(app.theme.selected_bg);
            for span in &mut line.spans {
                span.style = span.style.bg(app.theme.selected_bg);
            }
        }
        rendered_lines.push(line);
    }

    let p = Paragraph::new(rendered_lines);
    f.render_widget(p, area);
}

fn render_context_viewer(f: &mut Frame, app: &App, area: Rect) {
    let visible = app.visible_matches();
    if visible.is_empty() || app.selected_idx >= visible.len() {
        return;
    }

    let (_, match_item) = visible[app.selected_idx];
    let content = match fs::read_to_string(&match_item.file_path) {
        Ok(c) => c,
        Err(_) => return,
    };

    let file_lines: Vec<&str> = content.lines().collect();
    let target_line = match_item.line_number.saturating_sub(1);

    let height = area.height as usize;
    let half_height = height / 2;
    let start_line = target_line.saturating_sub(half_height);

    let mut rendered_lines = Vec::new();
    for (i, &l) in file_lines.iter().skip(start_line).take(height).enumerate() {
        let current_line_idx = start_line + i;
        let mut line = Line::from(l);
        if current_line_idx == target_line {
            line.style = line.style.bg(app.theme.selected_bg);
        }
        rendered_lines.push(line);
    }

    let p = Paragraph::new(rendered_lines);
    f.render_widget(p, area);
}

