            line.style = line.style.bg(app.theme.selected_bg);
            for span in &mut line.spans {
                span.style = span.style.bg(app.theme.selected_bg);
            }
        }
        rendered_lines.push(line);
    }

    let p = Paragraph::new(rendered_lines);
    f.render_widget(p, area);
}

fn render_context_viewer(f: &mut Frame, app: &App, area: Rect) {
    let visible = app.visible_matches();
    if visible.is_empty() || app.selected_idx >= visible.len() {
        return;
    }

    let (_, match_item) = visible[app.selected_idx];
    let content = match fs::read_to_string(&match_item.file_path) {
        Ok(c) => c,
        Err(_) => return,
    };

    let file_lines: Vec<&str> = content.lines().collect();
    let target_line = match_item.line_number.saturating_sub(1);

    let height = area.height as usize;
    let half_height = height / 2;
    let start_line = target_line.saturating_sub(half_height);

    let mut rendered_lines = Vec::new();
    for (i, &l) in file_lines.iter().skip(start_line).take(height).enumerate() {
        let current_line_idx = start_line + i;
        let mut line = Line::from(l);
        if current_line_idx == target_line {
            line.style = line.style.bg(app.theme.selected_bg);
        }
        rendered_lines.push(line);
    }

    let p = Paragraph::new(rendered_lines);
    f.render_widget(p, area);
}

fn render_status_bar(f: &mut Frame, app: &App, area: Rect) {
    let (badge_str, badge_bg) = match &app.search_status {
        SearchStatus::Searching => ("  SEARCHING ", Color::Rgb(255, 165, 0)),
        SearchStatus::Finished => ("  FINISHED  ", Color::Green),
        SearchStatus::Error(_) => ("    ERROR   ", Color::Red),
    };

    let badge_span = Span::styled(
        badge_str,
        Style::default()
            .bg(badge_bg)
            .fg(Color::Black)
            .add_modifier(Modifier::BOLD),
    );

    let mut msg_text = String::new();
    if let Some(err_msg) = &app.status_error_message {
        msg_text = format!(" {}", err_msg);
    } else {
        match &app.search_status {
            SearchStatus::Searching => {}
            SearchStatus::Finished => {
                let vis_matches = app.visible_matches().len();
                if vis_matches > 0 {
                    let match_str = if vis_matches == 1 { "match" } else { "matches" };
                    let vis_files = app.visible_files_count();
                    let file_str = if vis_files == 1 { "file" } else { "files" };
                    let filtered = app.filtered_matches_count();
                    if filtered > 0 {
                        msg_text = format!(
                            " Found {} {} in {} {} ({} filtered out).",
                            vis_matches, match_str, vis_files, file_str, filtered
                        );
                    } else {
                        msg_text = format!(
                            " Found {} {} in {} {}.",
                            vis_matches, match_str, vis_files, file_str
                        );
                    }
                } else {
                    msg_text = " No matches found.".to_string();
                }
            }
            SearchStatus::Error(e) => {
                msg_text = format!(" {}", e);
            }
        }
    }

    let vis_len = app.visible_matches().len();
    let current_pos = if vis_len > 0 { app.selected_idx + 1 } else { 0 };
    let counter_str = format!(" | {}/{}", current_pos, vis_len);

    let status_bg = match app.theme.selected_bg {
        Color::Rgb(58, 58, 58) => Color::Rgb(58, 58, 58),
        _ => Color::Reset,
    };

    let msg_span = Span::styled(
        msg_text.clone(),
        Style::default().bg(status_bg).fg(Color::Rgb(147, 147, 147)),
    );

    let counter_span = Span::styled(
        counter_str,
        Style::default().bg(status_bg).fg(Color::Rgb(147, 147, 147)),
    );

    // Padding between msg_span and counter_span
    let width = area.width as usize;
    let badge_len = badge_str.len();
    let msg_len = msg_text.len();
    let counter_len = counter_span.content.len();

    let padding_len = width.saturating_sub(badge_len + msg_len + counter_len);
    let padding_span = Span::styled(" ".repeat(padding_len), Style::default().bg(status_bg));

    let line = Line::from(vec![badge_span, msg_span, padding_span, counter_span]);
    let p = Paragraph::new(line);
    f.render_widget(p, area);
}

