        .unwrap_or_default();

    let paths = matches
        .get_many::<std::path::PathBuf>("paths")
        .map(|p| p.cloned().collect())
        .unwrap_or_else(|| vec![std::path::PathBuf::from(".")]);

    let ignore_case = matches.get_flag("ignore_case");
    let smart_case = matches.get_flag("smart_case");
    let hidden = matches.get_flag("hidden");
    let follow = matches.get_flag("follow");
    let word_regexp = matches.get_flag("word_regexp");
    let fixed_strings = matches.get_flag("fixed_strings");
    let multiline = matches.get_flag("multiline");

    let globs: Vec<String> = matches
        .get_many::<String>("glob")
        .map(|g| p_collect(g))
        .unwrap_or_default();

    let type_matching: Vec<String> = matches
        .get_many::<String>("type_matching")
        .map(|t| p_collect(t))
        .unwrap_or_default();

    let type_not: Vec<String> = matches
        .get_many::<String>("type_not")
        .map(|tn| p_collect(tn))
        .unwrap_or_default();

