        .get_one::<ContextViewer>("context_viewer")
        .unwrap_or(&ContextViewer::None);

    let sort = matches.get_one::<SortBy>("sort").cloned();
    let sortr = matches.get_one::<SortBy>("sortr").cloned();

    let theme_val = *matches.get_one::<Theme>("theme").unwrap_or(&Theme::Dark);
    let theme = match theme_val {
        Theme::Dark => ThemeColors::dark(),
        Theme::Light => ThemeColors::light(),
    };

    let editor_flag = matches.get_one::<Editor>("editor").cloned();
    let custom_cmd_flag = matches.get_one::<String>("custom_command").map(|s| s.as_str());

    let editor_cmd_template = match editor::get_editor_command(editor_flag, custom_cmd_flag) {
        Ok(tmpl) => tmpl,
        Err(err) => {
            eprintln!("Error: {}", err);
            std::process::exit(1);
        }
    };

    let search_opts = SearchOptions {
        pattern,
        paths,
        ignore_case,
        smart_case,
        hidden,
        follow,
        word_regexp,
        fixed_strings,
        multiline,
        globs,
        type_matching,
        type_not,
        sort,
        sortr,
    };

    // Pre-validate file types
    if let Err(e) = searcher::validate_file_types(&search_opts.type_matching) {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
    if let Err(e) = searcher::validate_file_types(&search_opts.type_not) {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }

    // Initialize TUI
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

