fn p_collect(iter: clap::parser::ValuesRef<String>) -> Vec<String> {
    iter.cloned().collect()
}

fn run_app(
    terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    app: &mut App,
) -> io::Result<()> {
    let mut pending_key: Option<(char, Instant)> = None;

    loop {
        terminal.draw(|f| ui::draw(f, app))?;

        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Press {
                    continue;
                }

                // Clear temporary error message on keypress
                app.status_error_message = None;

                if app.show_keymap_popup {
                    match key.code {
                        KeyCode::Down | KeyCode::Char('j') => app.keymap_scroll += 1,
                        KeyCode::Up | KeyCode::Char('k') => {
                            app.keymap_scroll = app.keymap_scroll.saturating_sub(1)
                        }
                        _ => app.show_keymap_popup = false,
                    }
                    continue;
                }

                if app.show_search_popup {
                    match key.code {
                        KeyCode::Char(c) => app.search_popup_input.push(c),
                        KeyCode::Backspace => {
                            app.search_popup_input.pop();
                        }
                        KeyCode::Esc => app.show_search_popup = false,
                        KeyCode::Enter => {
                            app.show_search_popup = false;
                            app.search_opts.pattern = app.search_popup_input.clone();
                            app.filtered_match_indices.clear();
                            app.filtered_file_paths.clear();
                            app.execute_search();
                        }
                        _ => {}
                    }
                    continue;
                }

                // Normal mode key events
                // Check pending two-key combos ('g' -> 'g' or 'd' -> 'd'/'w')
                if let Some((p_char, p_time)) = pending_key {
                    pending_key = None;
                    if p_time.elapsed() < Duration::from_millis(500) {
                        if p_char == 'g' {
                            if key.code == KeyCode::Char('g') {
                                app.move_first();
                                continue;
                            }
                        } else if p_char == 'd' {
                            if key.code == KeyCode::Char('d') {
                                app.filter_current_match();
                                continue;
                            } else if key.code == KeyCode::Char('w') {
                                app.filter_current_file();
                                continue;
                            }
                        }
                    }
                }

                match key.code {
                    KeyCode::Char('q') | KeyCode::Esc => return Ok(()),
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        return Ok(())
                    }

                    KeyCode::Char('?') | KeyCode::F(1) => {
                        app.show_keymap_popup = true;
                        app.keymap_scroll = 0;
                    }
                    KeyCode::Char('/') | KeyCode::F(5) => {
                        app.show_search_popup = true;
                        app.search_popup_input = app.search_opts.pattern.clone();
                    }

                    KeyCode::Down | KeyCode::Char('j') => app.move_down(),
                    KeyCode::Up | KeyCode::Char('k') => app.move_up(),
                    KeyCode::Home => app.move_first(),
                    KeyCode::End | KeyCode::Char('G') => app.move_last(),

                    KeyCode::Right | KeyCode::Char('l') | KeyCode::PageDown => {
                        app.move_next_file()
                    }
                    KeyCode::Left | KeyCode::Char('h') | KeyCode::PageUp => app.move_prev_file(),

                    KeyCode::Delete => app.filter_current_match(),

                    KeyCode::Char('g') => {
                        pending_key = Some(('g', Instant::now()));
                    }
                    KeyCode::Char('d') => {
                        pending_key = Some(('d', Instant::now()));
                    }

                    KeyCode::Char('v') => app.toggle_vertical_context(),
                    KeyCode::Char('s') => app.toggle_horizontal_context(),
                    KeyCode::Char('+') => app.increase_context_size(),
                    KeyCode::Char('-') => app.decrease_context_size(),

                    KeyCode::Char('n') => app.sort_by(SortBy::Path),
                    KeyCode::Char('m') => app.sort_by(SortBy::Modified),
                    KeyCode::Char('c') => app.sort_by(SortBy::Created),
                    KeyCode::Char('a') => app.sort_by(SortBy::Accessed),

                    KeyCode::Enter => {
                        open_selected_in_editor(terminal, app)?;
                    }

                    _ => {}
                }
            }
        }
    }
}

fn open_selected_in_editor(
    terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    app: &mut App,
) -> io::Result<()> {
    let visible = app.visible_matches();
    if visible.is_empty() || app.selected_idx >= visible.len() {
        return Ok(());
    }

    let (_, match_item) = visible[app.selected_idx];
    let file_path_str = match_item.file_path.to_string_lossy().to_string();
    let line_num_str = match_item.line_number.to_string();

    let cmd_str = app
        .editor_cmd_template
        .replace("{file_name}", &file_path_str)
        .replace("{line_number}", &line_num_str);

    let tokens = shlex::split(&cmd_str).unwrap_or_default();
    if tokens.is_empty() {
        app.status_error_message = Some("Invalid editor command".to_string());
        return Ok(());
    }

    let prog = &tokens[0];
    let args = &tokens[1..];

    // Suspend TUI
    disable_raw_mode()?;
    execute!(stdout(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    let status = Command::new(prog).args(args).status();

    // Re-enable TUI
    enable_raw_mode()?;
    execute!(stdout(), EnterAlternateScreen)?;
    terminal.clear()?;

    match status {
        Ok(s) if s.success() => {}
        _ => {
            app.status_error_message = Some(format!(
                "Failed to open editor '{}'. Is it installed?",
                prog
            ));
        }
    }

    Ok(())
}
